<script lang="ts">
	import { onMount } from 'svelte'; import { WEBUI_API_BASE_URL } from '$lib/constants';
	type Any = Record<string, any>;
	let tiers:Any[]=[]; let models:Any[]=[]; let users:Any[]=[]; let coupons:Any[]=[]; let invites:Any[]=[]; let overview:Any={}; let usage:Any[]=[];
	let tab='overview'; let notice=''; let error=''; let loading=true; let query=''; let selectedUser:Any=null;
	let coupon:Any={code:'',tier_id:'',free_days:0,percent_off:null,amount_off_cents:null,bonus_credits:0,max_redemptions:null,max_per_user:1,combinable:false,apply_after_current:true,active:true};
	let invitationOnly=false; let referralRewards=false; let referralDays=14;
	const api=async(path:string,init:RequestInit={})=>{const response=await fetch(`${WEBUI_API_BASE_URL}/usage${path}`,{...init,headers:{'Content-Type':'application/json',Authorization:`Bearer ${localStorage.token}`,...(init.headers||{})}});const body=await response.json().catch(()=>null);if(!response.ok)throw new Error(body?.detail||'Request failed');return body};
	const feedback=async(work:()=>Promise<any>,success:string)=>{notice='';error='';try{await work();notice=success;await load()}catch(e){error=e instanceof Error?e.message:String(e)}};
	const load=async()=>{loading=true;try{const data=await Promise.all([api('/admin/tiers'),api('/admin/model-candidates'),api('/admin/users'),api('/admin/coupons'),api('/admin/invites'),api('/admin/overview'),api('/admin/usage'),api('/admin/settings/invitation_only'),api('/admin/settings/referral_rewards_enabled'),api('/admin/settings/referral_reward_days')]);[tiers,models,users,coupons,invites,overview,usage]=data.slice(0,7);models=models.map((model:Any)=>({...model,rate:model.rate||{credits_per_50k:0,input_credits_per_50k:null,output_credits_per_50k:null,enabled:false,fair_use:false,stream_usage_supported:false}}));invitationOnly=Boolean(data[7].value);referralRewards=Boolean(data[8].value);referralDays=Number(data[9].value||14)}catch(e){error=e instanceof Error?e.message:String(e)}finally{loading=false}};
	onMount(load);
	const plan=()=>tiers=[...tiers,{id:`plan-${Date.now()}`,name:'New plan',monthly_credits:0,daily_limit:null,agent_credits:0,price_cents:null,currency:'EUR',planned_price:true,features:{},model_rules:{},active:true}];
	const savePlan=(item:Any)=>feedback(()=>api(`/admin/tiers/${item.id}`,{method:'PUT',body:JSON.stringify(item)}),'Plan saved');
	const saveModel=(model:Any)=>feedback(()=>api(`/admin/rates/${encodeURIComponent(model.id)}`,{method:'PUT',body:JSON.stringify(model.rate)}),'Model pricing saved');
	const assign=(tierId:string)=>feedback(()=>api('/admin/assign',{method:'POST',body:JSON.stringify({user_id:selectedUser.id,tier_id:tierId})}),'Subscription assigned');
	const adjust=(amount:number)=>feedback(()=>api('/admin/adjustments',{method:'POST',body:JSON.stringify({user_id:selectedUser.id,amount,bucket:'bonus',reason:'Administrator adjustment'})}),'Credits updated');
	const saveCoupon=()=>feedback(async()=>{const payload={...coupon,tier_id:coupon.tier_id||null};if(coupon.id)await api(`/admin/coupons/${coupon.id}`,{method:'PUT',body:JSON.stringify(payload)});else await api('/admin/coupons',{method:'POST',body:JSON.stringify(payload)});coupon={code:'',tier_id:'',free_days:0,percent_off:null,amount_off_cents:null,bonus_credits:0,max_redemptions:null,max_per_user:1,combinable:false,apply_after_current:true,active:true}},'Coupon saved');
	const saveInvite=(invite:Any,regenerate=false)=>feedback(()=>api(`/admin/invites/${invite.id}`,{method:'PUT',body:JSON.stringify({max_uses:Number(invite.max_uses),revoked:invite.revoked,regenerate})}),'Invitation saved');
	const saveSettings=()=>feedback(async()=>{await api('/admin/invitations/enabled?enabled='+invitationOnly,{method:'POST'});await api('/admin/settings/referral_rewards_enabled',{method:'PUT',body:JSON.stringify({value:referralRewards})});await api('/admin/settings/referral_reward_days',{method:'PUT',body:JSON.stringify({value:Number(referralDays)})})},'Settings saved');
	const filteredUsers=()=>users.filter((item:Any)=>`${item.name} ${item.email}`.toLowerCase().includes(query.toLowerCase()));
	const activeTiers=()=>tiers.filter((item:Any)=>item.active);
	const assignFromSelect=(event:Event)=>{const tierId=(event.currentTarget as HTMLSelectElement).value;if(tierId) assign(tierId)};
</script>
<main class="mx-auto max-w-7xl p-4 sm:p-7 dark:text-white">
	<div class="flex flex-wrap items-start justify-between gap-4"><div><h1 class="text-2xl font-semibold">Usage &amp; Billing</h1><p class="mt-1 text-sm opacity-70">Manage plans, model credits, invitations and promotions without API calls.</p></div><button class="rounded-xl bg-indigo-600 px-4 py-2 text-white" on:click={()=>{plan();tab='plans'}}>New plan</button></div>
	{#if error}<div class="mt-4 rounded-xl bg-red-50 p-3 text-sm text-red-700 dark:bg-red-950/40 dark:text-red-300">{error}</div>{/if}{#if notice}<div class="mt-4 rounded-xl bg-emerald-50 p-3 text-sm text-emerald-700 dark:bg-emerald-950/40 dark:text-emerald-300">{notice}</div>{/if}
	<nav class="mt-5 flex gap-2 overflow-x-auto pb-1">{#each [['overview','Overview'],['plans','Plans'],['models','Model pricing'],['users','Users'],['coupons','Coupons'],['invites','Invitations'],['analytics','Analytics'],['settings','Settings']] as entry}<button class="whitespace-nowrap rounded-full px-3 py-2 text-sm dark:bg-gray-800" class:bg-indigo-600={tab===entry[0]} class:text-white={tab===entry[0]} class:bg-gray-100={tab!==entry[0]} on:click={()=>tab=entry[0]}>{entry[1]}</button>{/each}</nav>
	{#if loading}<p class="py-12 text-center opacity-60">Loading billing management…</p>
	{:else if tab==='overview'}<section class="mt-5 grid gap-4 sm:grid-cols-2 lg:grid-cols-3">{#each [['Registered users',overview.users],['Active users',overview.active_users],['Credits consumed this month',overview.monthly_credits],['Tokens consumed',overview.tokens],['Active coupons',overview.active_coupons],['Successful invitations',overview.successful_invitations]] as metric}<article class="rounded-2xl border border-gray-100 bg-white p-5 shadow-sm dark:border-gray-800 dark:bg-gray-850"><p class="text-sm opacity-60">{metric[0]}</p><p class="mt-1 text-2xl font-semibold">{Number(metric[1]||0).toLocaleString()}</p></article>{/each}</section>
	{:else if tab==='plans'}<section class="mt-5 space-y-4">{#each tiers as item}<article class="rounded-2xl border border-gray-100 bg-white p-5 shadow-sm dark:border-gray-800 dark:bg-gray-850"><div class="grid gap-3 md:grid-cols-3"><label>Plan name<input bind:value={item.name} class="field"/></label><label>Monthly credits<input type="number" bind:value={item.monthly_credits} class="field"/></label><label>Daily limit <span class="opacity-50">(optional)</span><input type="number" bind:value={item.daily_limit} class="field"/></label><label>Monthly price, cents<input type="number" bind:value={item.price_cents} class="field"/></label><label>Agent credits<input type="number" bind:value={item.agent_credits} class="field"/></label><label class="pt-6"><input type="checkbox" bind:checked={item.active}/> Active plan</label></div><button class="primary mt-4" on:click={()=>savePlan(item)}>Save plan</button></article>{/each}</section>
	{:else if tab==='models'}<section class="mt-5 rounded-2xl border border-gray-100 bg-white p-5 shadow-sm dark:border-gray-800 dark:bg-gray-850"><p class="mb-3 text-sm opacity-70">Every registry model is configured here by its actual model ID.</p>{#each models as model}<div class="grid gap-3 border-b border-gray-100 py-4 last:border-0 md:grid-cols-[2fr_1fr_1fr_1fr_auto] dark:border-gray-800"><div><b>{model.name}</b><code class="block break-all text-xs opacity-60">{model.id}</code></div><label>Base / 50k<input type="number" bind:value={model.rate.credits_per_50k} class="field"/></label><label>Input / 50k<input type="number" bind:value={model.rate.input_credits_per_50k} class="field"/></label><label>Output / 50k<input type="number" bind:value={model.rate.output_credits_per_50k} class="field"/></label><label class="text-sm"><input type="checkbox" bind:checked={model.rate.enabled}/> Enabled<br/><input type="checkbox" bind:checked={model.rate.fair_use}/> Fair use<br/><input type="checkbox" bind:checked={model.rate.stream_usage_supported}/> Streaming usage</label><button class="primary self-end" on:click={()=>saveModel(model)}>Save</button></div>{/each}</section>
	{:else if tab==='users'}<section class="mt-5 grid gap-5 lg:grid-cols-[1.4fr_.6fr]"><article class="rounded-2xl border border-gray-100 bg-white p-5 shadow-sm dark:border-gray-800 dark:bg-gray-850"><input bind:value={query} class="field mb-3" placeholder="Search loaded users"/>{#each filteredUsers() as item}<button class="flex w-full justify-between gap-3 border-b border-gray-100 py-3 text-left dark:border-gray-800" on:click={()=>selectedUser=item}><span><b>{item.name}</b><small class="block opacity-60">{item.email}</small></span><span>{item.tier_id||'Free'}</span></button>{/each}</article><article class="rounded-2xl border border-gray-100 bg-white p-5 shadow-sm dark:border-gray-800 dark:bg-gray-850">{#if selectedUser}<h2 class="font-semibold">{selectedUser.name}</h2><label class="mt-4 block text-sm">Assign plan<select class="field" on:change={assignFromSelect}><option value="">Choose a plan</option>{#each activeTiers() as item}<option value={item.id}>{item.name}</option>{/each}</select></label><div class="mt-4 flex gap-2"><button class="primary" on:click={()=>adjust(100)}>+100 bonus credits</button><button class="secondary" on:click={()=>adjust(-100)}>-100 bonus credits</button></div>{:else}<p class="opacity-60">Select a user to manage their subscription and credits.</p>{/if}</article></section>
	{:else if tab==='coupons'}<section class="mt-5 grid gap-5 lg:grid-cols-[.8fr_1.2fr]"><article class="rounded-2xl border border-gray-100 bg-white p-5 shadow-sm dark:border-gray-800 dark:bg-gray-850"><h2 class="font-semibold">{coupon.id?'Edit coupon':'New coupon'}</h2><div class="mt-3 grid gap-3 sm:grid-cols-2"><label>Code<input bind:value={coupon.code} class="field" required/></label><label>Plan<select bind:value={coupon.tier_id} class="field"><option value="">No plan access</option>{#each tiers as item}<option value={item.id}>{item.name}</option>{/each}</select></label><label>Free days<input type="number" bind:value={coupon.free_days} class="field"/></label><label>Bonus credits<input type="number" bind:value={coupon.bonus_credits} class="field"/></label><label>Percent discount<input type="number" bind:value={coupon.percent_off} class="field"/></label><label>Fixed discount, cents<input type="number" bind:value={coupon.amount_off_cents} class="field"/></label><label>Maximum redemptions<input type="number" bind:value={coupon.max_redemptions} class="field"/></label><label>Per user<input type="number" bind:value={coupon.max_per_user} class="field"/></label><label><input type="checkbox" bind:checked={coupon.combinable}/> Combinable</label><label><input type="checkbox" bind:checked={coupon.apply_after_current}/> Apply after active access</label><label><input type="checkbox" bind:checked={coupon.active}/> Active</label></div><div class="mt-4 flex gap-2"><button class="primary" on:click={saveCoupon}>Save coupon</button><button class="secondary" on:click={()=>coupon={code:'',tier_id:'',free_days:0,bonus_credits:0,max_per_user:1,combinable:false,apply_after_current:true,active:true}}>Clear</button></div></article><article class="rounded-2xl border border-gray-100 bg-white p-5 shadow-sm dark:border-gray-800 dark:bg-gray-850"><h2 class="font-semibold">Existing coupons</h2>{#each coupons as item}<button class="flex w-full justify-between border-b border-gray-100 py-3 text-left dark:border-gray-800" on:click={()=>coupon={...item,tier_id:item.tier_id||''}}><code>{item.code}</code><span>{item.redemptions} redeemed · {item.active?'Active':'Disabled'}</span></button>{:else}<p class="py-5 opacity-60">No coupons created yet.</p>{/each}</article></section>
	{:else if tab==='invites'}<section class="mt-5 rounded-2xl border border-gray-100 bg-white p-5 shadow-sm dark:border-gray-800 dark:bg-gray-850"><h2 class="font-semibold">Invitation codes</h2>{#each invites as item}<div class="grid gap-3 border-b border-gray-100 py-4 md:grid-cols-[2fr_1fr_auto_auto] dark:border-gray-800"><span><code>{item.code}</code><small class="block opacity-60">{item.creator_name||'Administrator'} · {item.uses}/{item.max_uses} used</small></span><label>Allowed uses<input type="number" bind:value={item.max_uses} class="field"/></label><label class="pt-6"><input type="checkbox" bind:checked={item.revoked}/> Disabled</label><span class="flex gap-2"><button class="primary" on:click={()=>saveInvite(item)}>Save</button><button class="secondary" on:click={()=>saveInvite(item,true)}>Regenerate</button></span></div>{:else}<p class="py-5 opacity-60">No invitation codes yet.</p>{/each}</section>
	{:else if tab==='analytics'}<section class="mt-5 rounded-2xl border border-gray-100 bg-white p-5 shadow-sm dark:border-gray-800 dark:bg-gray-850">{#each usage as item}<div class="flex justify-between gap-4 border-b border-gray-100 py-3 text-sm dark:border-gray-800"><span>{item.user_id} · {item.model_id}</span><span>{Number(item.input_tokens)+Number(item.output_tokens)} tokens · {Number(item.credits).toFixed(3)} credits</span></div>{:else}<p class="py-5 opacity-60">No metered usage yet.</p>{/each}</section>
	{:else}<section class="mt-5 rounded-2xl border border-gray-100 bg-white p-5 shadow-sm dark:border-gray-800 dark:bg-gray-850"><h2 class="font-semibold">Registration and referrals</h2><label class="mt-4 block"><input type="checkbox" bind:checked={invitationOnly}/> Require invitation code for registration</label><label class="mt-3 block"><input type="checkbox" bind:checked={referralRewards}/> Enable referral rewards after public launch</label><label class="mt-3 block">Referral reward days<input type="number" min="1" max="365" bind:value={referralDays} class="field max-w-xs"/></label><button class="primary mt-4" on:click={saveSettings}>Save settings</button></section>{/if}
</main>
<style>.field{display:block;width:100%;margin-top:.35rem;border-radius:.6rem;border:1px solid rgb(209 213 219);background:transparent;padding:.55rem .7rem;font-size:.875rem}.primary{border-radius:.6rem;background:#4f46e5;color:white;padding:.55rem .9rem;font-size:.875rem}.secondary{border-radius:.6rem;background:#e5e7eb;padding:.55rem .9rem;font-size:.875rem}.dark .secondary{background:#374151}</style>
